# argument to parameter 'Path' because it is null") and
# `$ErrorActionPreference = "Stop"` aborts the install before anything is
# downloaded. Resolve the shell folders instead of trusting the environment;
# the abort stays fatal only once every fallback is exhausted.
if (-not $env:LOCALAPPDATA) {
    $env:LOCALAPPDATA = [Environment]::GetFolderPath('LocalApplicationData')
}
if (-not $env:LOCALAPPDATA -and $env:USERPROFILE) {
    $env:LOCALAPPDATA = Join-Path $env:USERPROFILE 'AppData\Local'
}
if (-not $env:APPDATA) {
    $env:APPDATA = [Environment]::GetFolderPath('ApplicationData')
}
if (-not $env:APPDATA -and $env:USERPROFILE) {
    $env:APPDATA = Join-Path $env:USERPROFILE 'AppData\Roaming'
}
if (-not $env:LOCALAPPDATA) {
    Write-Err "cannot resolve LOCALAPPDATA - it is unset and no user profile folder is known."
    # throw, not exit: `exit` closes the caller's console under `irm | iex`.
    throw "cannot resolve LOCALAPPDATA - set it, then rerun the installer."
}
# TEMP is the same class of hazard: the archive and the extraction directory
# both hang off it.
if (-not $env:TEMP) {
    $env:TEMP = [IO.Path]::GetTempPath()
}
$installDir = Join-Path $env:LOCALAPPDATA "Fa"
$binDir = Join-Path $installDir "bin"

if (-not (Test-Path $binDir)) {
    New-Item -ItemType Directory -Force -Path $binDir | Out-Null
}
$target = Join-Path $binDir "$BinaryName.exe"

# ── 3. Resolve download URL ──────────────────────────────────────────────────

# ── 4. Install bundle (or fall back to Dart) ────────────────────────────────
# Only windows-x64 is published (scripts/release_required_assets.txt), so an
# arm64 miss must retry x64 -- that binary runs under Windows' x64 emulation
# -- instead of sending the user off to install the Dart SDK.
# An unexpected bundle layout used to be reported as a successful install
# (lib/ copied, no executable, "Installation complete"); it is fatal now.
function Install-FaBundle([string]$archName) {
    $url = "https://github.com/$Repo/releases/latest/download/fa-windows-$archName.zip"
    $archive = Join-Path $env:TEMP "fa-windows-$archName.zip"
    $extractDir = Join-Path $env:TEMP "fa-extract-$(Get-Random)"
    Write-Info "Downloading Fa for windows-$archName..."
    Invoke-WebRequest -Uri $url -OutFile $archive -UseBasicParsing -MaximumRedirection 5
    try {
        # dart build cli produces: bundle/{bin/fa.exe, lib/*.dll}
        # We rename it to fa.exe and extract into the install directory.
        Expand-Archive -Path $archive -DestinationPath $extractDir -Force
        $bundleDir = Join-Path $extractDir "bundle"
        $srcExe = Join-Path $bundleDir "bin\fa.exe"
        if (-not (Test-Path $srcExe)) {
            # Older bundles shipped the binary as fah.exe.
            $srcExe = Join-Path $bundleDir "bin\fah.exe"
        }
        if (-not (Test-Path $srcExe)) {
            $listing = @(
                Get-ChildItem $bundleDir -Recurse -File -ErrorAction SilentlyContinue |
                    ForEach-Object { $_.FullName.Substring($bundleDir.Length + 1) }
            )
            throw "the downloaded bundle has no bin\fa.exe (contents: $($listing -join ', '))"
        }
        try {
            Copy-Item $srcExe $target -Force
        } catch [System.IO.IOException] {
            throw "cannot replace $target - a running Fa process is using it. Close every Fa window, then rerun the installer."
        }
        $srcLib = Join-Path $bundleDir "lib"
        if (Test-Path $srcLib) {
            $libDir = Join-Path $installDir "lib"
            if (-not (Test-Path $libDir)) {
                New-Item -ItemType Directory -Force -Path $libDir | Out-Null
            }
            Copy-Item "$srcLib\*" $libDir -Force -Recurse
        }
        # Copy version.txt next to the binary so `fa --version` reports the real
        # release (gh-1945: without it the CLI falls back to a hardcoded 0.1.0 —
        # the installer layout probe reads <exe_dir>\version.txt).
        $srcVersion = Join-Path $bundleDir "version.txt"
        if (Test-Path $srcVersion) {
            Copy-Item $srcVersion (Join-Path $binDir "version.txt") -Force
        }
    } finally {
        Remove-Item -Recurse -Force $extractDir -ErrorAction SilentlyContinue
        Remove-Item $archive -ErrorAction SilentlyContinue
    }
    Write-Ok "Downloaded and installed $target"
}

# Windows PowerShell 5.1 on a host whose .NET default still offers only older
# protocols fails the download with "underlying connection was closed".
try {
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 -bor [Net.ServicePointManager]::SecurityProtocol
} catch { }

# Windows locks a running executable, so an in-place upgrade over an open TUI
# fails with a bare "being used by another process" (and then wrongly walks
# into the Dart fallback). Say what to do instead.
$faRunning = @(
    Get-Process -Name fa, fah -ErrorAction SilentlyContinue |
        Where-Object { $_.Path -and $_.Path.StartsWith($installDir, [StringComparison]::OrdinalIgnoreCase) }
)
if ($faRunning.Count -gt 0) {
    Write-Err "Fa is running from $installDir (PID $($faRunning.Id -join ', '))."
    Write-Host ""
    Write-Host "  Close every Fa window, then run the installer again."
    Write-Host ""
    throw "Fa is running - close it before reinstalling."
}

# arm64 first, then the published x64 build (emulated). ia32 has no fallback:
# a 32-bit binary cannot run the x64 build.
$candidates = if ($arch -eq 'arm64') { @('arm64', 'x64') } else { @($arch) }
$ProgressPreference = 'SilentlyContinue'
$installed = $false
$bundleError = $null
foreach ($candidate in $candidates) {
    if ($candidate -ne $arch) {
        Write-Warn "No prebuilt bundle for windows-$arch; trying windows-$candidate (runs under x64 emulation)."
    }
    try {
        Install-FaBundle $candidate
        $arch = $candidate
        $installed = $true
        break
    } catch {
        $bundleError = $_
        $status = $null
        try { $status = [int]$_.Exception.Response.StatusCode } catch { }
        # 404 means "nothing published for this platform": the next candidate
        # is worth a try. Anything else (TLS, disk, truncated zip) is a real
        # failure and must not be masked by the fallback candidate.
        if ($status -ne 404) { break }
    }
}

if (-not $installed) {
    $status = $null
    if ($bundleError) { try { $status = [int]$bundleError.Exception.Response.StatusCode } catch { } }
    if ($status -eq 404) {
        Write-Warn "No prebuilt bundle found for windows-$arch. Falling back to Dart pub global activate."
    } elseif ($status) {
        Write-Warn "Bundle download failed (HTTP $status). Falling back to Dart pub global activate."
    } else {
        Write-Warn "Bundle install failed: $($bundleError.Exception.Message)"
        Write-Warn "Falling back to Dart pub global activate."
    }
    $dart = Get-Command dart -ErrorAction SilentlyContinue
    if (-not $dart) {
        Write-Err "the Dart SDK ('dart') is not on your PATH, and no prebuilt binary is available for windows-$arch."
        Write-Host ""
        Write-Host "  Install Flutter (includes Dart) from:"
        Write-Host ""
        Write-Host "    https://docs.flutter.dev/get-started/install"
        Write-Host ""
        # `exit` would close the caller's console when this runs through
        # `irm ... | iex`; throw keeps the session alive and still makes
        # `powershell -File` exit non-zero (install.bat checks that code).
        throw "Fa was not installed: no prebuilt bundle for windows-$arch and no Dart SDK on PATH."
    }
    Write-Info "Activating flutter_agent_harness from pub.dev..."
    & dart pub global activate flutter_agent_harness
    $pubCacheBin = if ($env:PUB_CACHE_BIN) { $env:PUB_CACHE_BIN } else { Join-Path $env:LOCALAPPDATA "Pub\Cache\bin" }
    if (-not (Test-Path $pubCacheBin)) { $pubCacheBin = Join-Path $env:APPDATA "Pub\Cache\bin" }
    $binDir = $pubCacheBin
    $target = Join-Path $binDir "$BinaryName.bat"
}

# Smoke: a bundle can install and still not run (antivirus ate lib/, blocked
# binary). The installer used to print "Installation complete" blind.
if ($installed) {
    try {
        $probeOut = & $target --version 2>&1
        if ($LASTEXITCODE -ne 0) {
            Write-Warn "the installed binary exited $LASTEXITCODE on --version: $probeOut"
            Write-Warn "check that $installDir\lib\sqlite3.dll survived your antivirus, then reinstall."
        }
    } catch {
        Write-Warn "the installed binary did not run: $($_.Exception.Message)"
        Write-Warn "check that $installDir\lib\sqlite3.dll survived your antivirus, then reinstall."
    }
}

# ── 5. Ensure the bin directory is on the user PATH ──────────────────────────
$userPath = [Environment]::GetEnvironmentVariable("Path", "User")
$pathParts = $userPath -split ';' | ForEach-Object { $_.Trim() } | Where-Object { $_ }
if ($binDir -notin $pathParts) {
    Write-Info "Adding $binDir to your user PATH"
    $newPath = "$binDir;$userPath"
    [Environment]::SetEnvironmentVariable("Path", $newPath, "User")
}

# Refresh PATH in the current session so `fa` works immediately.
$env:Path = "$binDir;" + [Environment]::GetEnvironmentVariable("Path", "Machine") + ";" + [Environment]::GetEnvironmentVariable("Path", "User")

$faCmd = Get-Command fa -ErrorAction SilentlyContinue
if (-not $faCmd) { $faCmd = Get-Command fah -ErrorAction SilentlyContinue }
if ($faCmd) {
    Write-Ok "'fa' is on PATH ($($faCmd.Source))."
} else {
    Write-Warn "'fa' is not on PATH yet. The executable lives in $binDir"
    Write-Host ""
    Write-Warn "Open a new PowerShell window, or run this in the current one:"
    Write-Host ""
    Write-Host "    `$env:Path = `$env:Path + ';$binDir'"
    Write-Host ""
}

# ── 6. Done ──────────────────────────────────────────────────────────────────
Write-Host ""
Write-Ok "Installation complete."
Write-Host ""
Write-Host "  Configure a provider and API key interactively:"
Write-Host ""
if ($env:FA_INSTALL_VIA -eq "cmd") {
    Write-Host '    powershell -NoProfile -ExecutionPolicy Bypass -Command "irm https://fa1.dev/setup.ps1 | iex"'
    Write-Host ""
    Write-Host "  Or set an environment variable manually (cmd):"
    Write-Host ""
    Write-Host '    set OPENROUTER_API_KEY=<your-key>'
    Write-Host ""
    Write-Host '    (or: set ANTHROPIC_API_KEY / GOOGLE_API_KEY / OPENAI_API_KEY)'
    Write-Host ""
    Write-Host '  (from PowerShell: irm https://fa1.dev/setup.ps1 | iex)'
} else {
    Write-Host "    irm https://fa1.dev/setup.ps1 | iex"
    Write-Host ""
    Write-Host "  Or set an environment variable manually:"
    Write-Host ""
    Write-Host "    `$env:OPENROUTER_API_KEY = '<your-key>'   # or ANTHROPIC_API_KEY / GOOGLE_API_KEY / OPENAI_API_KEY"
}
Write-Host ""
Write-Host "  Then start the agent:"
Write-Host ""
Write-Host "    fa"
Write-Host ""
Write-Host "  Or run a single headless task:"
Write-Host ""
Write-Host "    fa `"summarize CHANGELOG.md`""
Write-Host ""
Write-Host "  (the legacy command 'fah' also works)"
Write-Host ""
Write-Host "  Docs:    https://github.com/IstiN/flutter_agent_harness"
Write-Host "  Package: https://pub.dev/packages/flutter_agent_harness"
Write-Host ""

#!/usr/bin/env dart

// Generates site/install.sh, site/install.ps1, site/install.bat,
// site/setup.sh and site/setup.ps1.
//
// Sources:
//   site/install-config.yaml  — banner, signing anchor, setup recipe, agent modes
//   site/install.sh.template / .ps1 / .bat
//   site/setup.sh.template / site/setup.ps1.template
//   lib/src/model_roles/provider_catalog.dart — the LIVE provider table
//     (gh-1596 AC6: the wizard's provider list, adapter kinds, endpoints and
//     key-env names are generated from the catalog, never hand-maintained)
//   lib/src/approval/approval.dart — the ApprovalMode enum (the wizard's
//     approval menu == always-ask/write/yolo/autopilot, AC6)
//   lib/src/cli/model_presets.dart — the CLI's offline model presets
//     (the wizard's model menus, AC6)
//
// After editing any source, rerun this script and commit the generated
// installer files. Do not edit install.sh / setup.sh / *.ps1 by hand —
// the golden drift test (test/site/installer_golden_test.dart) fails on
// drift, including catalog drift without regeneration.

import 'dart:io';

import 'package:flutter_agent_harness/src/approval/approval.dart';
import 'package:flutter_agent_harness/src/cli/model_presets.dart';
import 'package:flutter_agent_harness/src/model_roles/provider_catalog.dart';
import 'package:yaml/yaml.dart';

const _configPath = 'site/install-config.yaml';
const _shTemplatePath = 'site/install.sh.template';
const _psTemplatePath = 'site/install.ps1.template';
const _batTemplatePath = 'site/install.bat.template';
const _shOut = 'site/install.sh';
const _psOut = 'site/install.ps1';
const _batOut = 'site/install.bat';
const _shSetupTemplatePath = 'site/setup.sh.template';
const _psSetupTemplatePath = 'site/setup.ps1.template';
const _shSetupOut = 'site/setup.sh';
const _psSetupOut = 'site/setup.ps1';

final _generatedHeader =
    '''
# ═══════════════════════════════════════════════════════════════════════════
#  DO NOT EDIT THIS FILE BY HAND. It is generated from site/install-config.yaml
#  by `dart run scripts/gen_installers.dart`.
# ═══════════════════════════════════════════════════════════════════════════
'''
        .trim();

/// Renders every generated installer artifact WITHOUT touching the
/// filesystem. Keys are repo-relative paths, values are the exact bytes to
/// commit (gh-1945: the .ps1 entries are BOM-less — see [main]).
///
/// Exposed for the golden drift test (test/site/installer_golden_test.dart):
/// the test re-renders from the live sources and compares against the
/// committed tree, so a catalog/preset/approval change without
/// regeneration fails the suite.
Map<String, String> renderInstallers() {
  final config = loadYaml(File(_configPath).readAsStringSync()) as YamlMap;
  final modes = config['modes'] as YamlList;
  final installConfig = config['install'] as YamlMap;

  final shBanner = _shBanner(installConfig);
  final psBanner = _psBanner(installConfig);
  final shRecipe = _shSetupRecipe(installConfig);
  final psRecipe = _psSetupRecipe(installConfig);

  // SEC-07 (#795): the default install tracks the `vpinned` release marker
  // (advanced by the tag-scoped install-pin-bump job only after signed
  // provenance) — there is deliberately NO version knob here: a pin baked
  // into a committed file rots (#1015) or demands release-pipeline commits.
  // The trust anchor below stays single-sourced.

  // gh-814 r2: the trust anchor is single-sourced here. Hard-error when the
  // config carries no parseable-looking PUBLIC KEY block — a silently
  // missing anchor would produce an installer that can never verify.
  final signingPem = (installConfig['signing_public_key'] as String? ?? '')
      .trim();
  if (!signingPem.startsWith('-----BEGIN PUBLIC KEY-----') ||
      !signingPem.endsWith('-----END PUBLIC KEY-----')) {
    throw StateError(
      'install.signing_public_key in $_configPath must be a PUBLIC KEY PEM '
      'block (the release-signing trust anchor embedded via {{SIGNING_PEM}})',
    );
  }

  final providers = _wizardProviders();
  final approvalModes = _wizardApprovalModes();

  final sh = File(_shTemplatePath)
      .readAsStringSync()
      .replaceFirst('# {{GENERATED_HEADER}}', _generatedHeader)
      .replaceFirst('{{BANNER}}', shBanner)
      .replaceFirst('{{SIGNING_PEM}}', signingPem)
      .replaceFirst('{{SETUP_RECIPE}}', shRecipe)
      .replaceFirst('{{PROVIDER_MENU}}', _shProviderMenu(providers))
      .replaceFirst('{{PROVIDER_CASES}}', _shProviderCases(providers))
      .replaceFirst('{{MODE_MENU}}', _shModeMenu(modes))
      .replaceFirst('{{MODE_CASES}}', _shModeCases(modes))
      .replaceFirst('{{APPROVAL_MENU}}', _shApprovalMenu(approvalModes))
      .replaceFirst('{{APPROVAL_CASES}}', _shApprovalCases(approvalModes));

  final ps = File(_psTemplatePath)
      .readAsStringSync()
      .replaceFirst('# {{GENERATED_HEADER}}', _generatedHeader)
      .replaceFirst('{{BANNER}}', psBanner)
      .replaceFirst('{{SETUP_RECIPE}}', psRecipe)
      .replaceFirst('{{PROVIDER_MENU}}', _psProviderMenu(providers))
      .replaceFirst('{{PROVIDER_SWITCH}}', _psProviderSwitch(providers))
      .replaceFirst('{{MODE_MENU}}', _psModeMenu(modes))
      .replaceFirst('{{MODE_SWITCH}}', _psModeSwitch(modes))
      .replaceFirst('{{APPROVAL_MENU}}', _psApprovalMenu(approvalModes))
      .replaceFirst('{{APPROVAL_SWITCH}}', _psApprovalSwitch(approvalModes));

  // cmd.exe parses a .bat by BYTE offset and re-reads it as it executes. An
  // LF-only file makes it resume mid-line, so it runs fragments of the next
  // comment -- the wrapper dies with `'. was unexpected at this time.'`
  // before PowerShell ever starts. `.gitattributes` pins the checkout to
  // CRLF, but the renderer must not depend on that: force CRLF here so the
  // artifact is cmd-safe however it was produced. Multi-byte UTF-8 glyphs
  // are what turn the mis-seek into command fragments, so the body stays
  // ASCII-only too -- the banner box in [_generatedHeader] becomes plain `=`
  // in this flavour. Verified by test/site/installer_golden_test.dart.
  final batHeader = _generatedHeader
      .replaceAll('# ', ':: ')
      .replaceAll('\u2550', '=');
  final bat = File(_batTemplatePath)
      .readAsStringSync()
      .replaceFirst(':: {{GENERATED_HEADER}}', batHeader)
      .replaceAll('\r\n', '\n')
      .replaceAll('\n', '\r\n');

  final shSetup = File(_shSetupTemplatePath)
      .readAsStringSync()
      .replaceFirst('# {{GENERATED_HEADER}}', _generatedHeader)
      .replaceFirst('{{PROVIDER_MENU}}', _shProviderMenu(providers))
      .replaceFirst('{{PROVIDER_CASES}}', _shProviderCases(providers))
      .replaceFirst('{{MODE_MENU}}', _shModeMenu(modes))
      .replaceFirst('{{MODE_CASES}}', _shModeCases(modes))
      .replaceFirst('{{APPROVAL_MENU}}', _shApprovalMenu(approvalModes))
      .replaceFirst('{{APPROVAL_CASES}}', _shApprovalCases(approvalModes));

  final psSetup = File(_psSetupTemplatePath)
      .readAsStringSync()
      .replaceFirst('# {{GENERATED_HEADER}}', _generatedHeader)
      .replaceFirst('{{PROVIDER_MENU}}', _psProviderMenu(providers))
      .replaceFirst('{{PROVIDER_SWITCH}}', _psProviderSwitch(providers))
      .replaceFirst('{{MODE_MENU}}', _psModeMenu(modes))
      .replaceFirst('{{MODE_SWITCH}}', _psModeSwitch(modes))
      .replaceFirst('{{APPROVAL_MENU}}', _psApprovalMenu(approvalModes))
      .replaceFirst('{{APPROVAL_SWITCH}}', _psApprovalSwitch(approvalModes));

  return {
    _shOut: sh,
    _batOut: bat,
    _shSetupOut: shSetup,
    // gh-1945: the .ps1 content is committed BOM-less — the piped
    // `irm | iex` path decodes the served bytes as ISO-8859-1, where a BOM
    // becomes literal `ï»¿` text. The golden test asserts bytes 0-2 are NOT
    // a BOM (see test/site/installer_golden_test.dart).
    _psOut: ps,
    _psSetupOut: psSetup,
  };
}

void main() {
  final rendered = renderInstallers();
  for (final entry in rendered.entries) {
    // gh-1945: NO UTF-8 BOM on the .ps1 artifacts. The served file is piped
    // (`irm https://fa1.dev/install.ps1 | iex`) and GitHub Pages serves .ps1
    // as application/octet-stream with no charset, so Windows PowerShell 5.1
    // decodes the body as ISO-8859-1: the BOM bytes become the literal text
    // `ï»¿` glued to line 1, the leading `#` stops being a comment, and the
    // install fails with "The term 'ï»¿#' is not recognized". A BOM-less
    // file starts with plain ASCII `#`, which is decode-invariant in every
    // ANSI code page; the non-ASCII glyphs sit inside comments/string
    // literals, where a Latin-1 mis-decode is cosmetic, never syntactic.
    // (The BOM's parse-time benefit only applied to `powershell -File`
    // execution, which no documented flow uses; PS 7 decodes UTF-8 either
    // way. Golden test: test/site/installer_golden_test.dart.)
    File(entry.key).writeAsStringSync(entry.value);
  }
  print('Generated ${rendered.keys.join(', ')} from $_configPath');
}

// ── Wizard data (gh-1596 AC6) ───────────────────────────────────────────────

/// One wizard provider row: the identity/data half comes from the live
/// catalog ([ProviderSpec]), the display half from [_providerMeta].
final class _WizardProvider {
  const _WizardProvider({
    required this.id,
    required this.kind,
    required this.name,
    required this.note,
    required this.recommended,
    required this.baseUrl,
    required this.keyVar,
    required this.models,
    required this.custom,
  });

  /// The config/choice id (`provider="openrouter"`).
  final String id;

  /// The catalog adapter kind — the config.yaml `provider:` value
  /// (canonicalProviderKind boundary).
  final String kind;

  /// Menu display name.
  final String name;

  /// Menu note after the dash.
  final String note;

  final bool recommended;

  final String baseUrl;

  /// The API-key env var the wizard offers to persist.
  final String keyVar;

  /// Preset model ids, in menu order; the first carries `(recommended)`.
  /// Empty = the wizard asks for the model id directly (no fake menu).
  final List<String> models;

  /// The synthesized `custom` row (endpoint + model asked, menu skipped).
  final bool custom;
}

/// Curated display metadata for every wizard provider. The catalog owns
/// the LIST; this map owns only how each row reads on screen. A catalog
/// provider without an entry here hard-errors the generation (the drift
/// guard — a new provider must ship with its wizard copy).
const _providerMeta = <String, (String, String)>{
  'openrouter': ('OpenRouter', 'one key, many models'),
  'aiin': ('AIIN', 'AIIN chat'),
  'kimi': ('Kimi', 'Moonshot Kimi for Coding'),
  'openai': ('OpenAI', 'GPT'),
  'chatgpt': ('ChatGPT', 'Codex — OAuth credentials'),
  'copilot': ('GitHub Copilot', 'your GitHub token'),
  'codemie': ('CodeMie', 'EPAM CodeMie'),
  'dial': ('DIAL', 'EPAM AI DIAL'),
  'minimax': ('MiniMax', 'MiniMax chat'),
  'anthropic': ('Anthropic', 'Claude'),
  'google': ('Google', 'Gemini'),
  'zai': ('Z.AI', 'GLM coding plan'),
  'custom': ('Custom', 'any OpenAI-compatible endpoint'),
};

/// The wizard provider list (AC6): openrouter first (recommended), then
/// the rest by catalog order, `custom` synthesized last.
List<_WizardProvider> _wizardProviders() {
  _WizardProvider row(String id, {bool recommended = false}) {
    final spec = providerCatalog[id];
    if (spec == null) {
      throw StateError(
        'provider_catalog has no "$id" — the wizard presets are generated '
        'from the live catalog (gh-1596 AC6); fix _wizardProviders',
      );
    }
    final meta = _providerMeta[id];
    if (meta == null) {
      throw StateError(
        'no wizard display metadata for catalog provider "$id" — add a '
        '_providerMeta entry (name + note) and regenerate the installers',
      );
    }
    return _WizardProvider(
      id: spec.name,
      kind: spec.kind,
      name: meta.$1,
      note: meta.$2,
      recommended: recommended,
      baseUrl: spec.defaultBaseUrl,
      keyVar: spec.apiKeyEnvNames.first,
      models: knownModelPresets[spec.name] ?? const [],
      custom: false,
    );
  }

  return [
    row('openrouter', recommended: true),
    for (final spec in providerCatalog.values)
      if (spec.name != 'openrouter') row(spec.name),
    // `custom` is not a catalog entry: the guided any-endpoint flow.
    _WizardProvider(
      id: 'custom',
      kind: 'openai-completions',
      name: _providerMeta['custom']!.$1,
      note: _providerMeta['custom']!.$2,
      recommended: false,
      baseUrl: '',
      keyVar: 'OPENAI_API_KEY',
      models: const [],
      custom: true,
    ),
  ];
}

/// Curated menu notes per approval-mode label.
const _approvalNotes = <String, String>{
  'always-ask': 'prompt before every tool call',
  'write': 'prompt before writes/executes',
  'yolo': 'run safe tools unattended',
  'autopilot': 'never prompt — for unattended runs',
};

/// The wizard's default approval mode (the CLI default, cli_config.dart).
const _approvalDefault = 'yolo';

final class _WizardApprovalMode {
  const _WizardApprovalMode(this.id, this.note, this.isDefault);

  final String id;
  final String note;
  final bool isDefault;
}

/// The approval-mode list (AC6): the live [ApprovalMode] enum order —
/// always-ask, write, yolo, autopilot (kAutopilotLabel).
List<_WizardApprovalMode> _wizardApprovalModes() {
  final labels = [for (final mode in ApprovalMode.values) mode.label];
  return [
    for (final label in labels)
      _WizardApprovalMode(
        label,
        _approvalNotes[label] ??
            (throw StateError(
              'no wizard note for approval mode "$label" — add an '
              '_approvalNotes entry and regenerate the installers',
            )),
        label == _approvalDefault,
      ),
  ];
}

