Write-Host ""
Write-Host "  Fa setup wizard — flutter_agent_harness CLI (Windows)"
Write-Host ""

# ── 1. Verify CLI is installed ───────────────────────────────────────────────
$faCmd = Get-Command fa -ErrorAction SilentlyContinue
if (-not $faCmd) { $faCmd = Get-Command fah -ErrorAction SilentlyContinue }
# The installer updates the *user* PATH, which only new logons pick up: run
# right after it, this session still misses the directory and the wizard used
# to claim the CLI was never installed. Probe where the installer puts it.
if (-not $faCmd) {
    $faLocalRoot = if ($env:LOCALAPPDATA) { $env:LOCALAPPDATA } else { Join-Path $env:USERPROFILE 'AppData\Local' }
    $faBin = Join-Path $faLocalRoot 'Fa\bin'
